use Kulturhus\Verein\Finance;
$db=TestSupport::db();SchemaRegistry::install($db);$n=0;
$check=static function(bool $ok,string $label)use(&$n){if(!$ok)throw new RuntimeException($label);$n++;echo "PASS $label\n";};$key=static fn()=>bin2hex(random_bytes(16));
$db->exec("INSERT INTO clubs VALUES('own-list-club','Own source club'),('source-foreign','Foreign source club');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('own-list-admin','own-list-club','member',1),('own-list-reader','own-list-club','member',0),('own-list-foreign','source-foreign','member',1);INSERT INTO settings_roles(club_id,id,name,description,members_access,finance_access,settings_access,version) VALUES('own-list-club','source-reader','Own finance reader','','none','read',0,1);INSERT INTO settings_role_assignments VALUES('own-list-reader','own-list-club','source-reader',1)");
$f=new Finance($db,'own-list-admin');$foreign=new Finance($db,'own-list-foreign');$bank=$f->createAccount('Own bank <source> 0','offline','1000','2020-01-01');$cash=$f->createAccount('Own cash 0','cash','1000','2020-01-01');$foreignAccount=$foreign->createAccount('Foreign secret source','offline','0','2020-01-01');
$foreignTransaction=$foreign->createTransaction(['account'=>$foreignAccount,'booked_on'=>'2026-10-01','direction'=>'income','amount'=>'50','description'=>'Foreign secret source'],$key());
$cases=[];foreach(['front-nojs','front-js','direct-nojs','direct-js'] as $i=>$case){$account=$i%2?$cash:$bank;foreach(['income','expense'] as $direction){$description='Own original '.$case.' '.$direction.' <em>0</em> ä🙂';$id=$f->createTransaction(['account'=>$account,'booked_on'=>'2026-10-01','direction'=>$direction,'amount'=>'50','counterparty'=>'Own party '.$case,'description'=>$description],$key());$cases[$case][$direction]=['id'=>$id,'account'=>$account,'description'=>$description,'kind'=>$direction==='income'&&$i>1?'contribution':$direction];}}
// Prefer the intended older source over more than one page of newer originals.
foreach([$bank,$cash] as $account)for($i=0;$i<25;$i++)$f->createTransaction(['account'=>$account,'booked_on'=>'2026-10-02','direction'=>'income','amount'=>'50','description'=>'Newer unrelated original '.$i],$key());
$probe=$f->createEntry(['kind'=>'income','description'=>'Own guide probe','amount'=>'20','category'=>'general','document_date'=>'2026-10-01','due_date'=>'2026-10-01'],$key());
$render=static function(string $template,Finance $finance,array $query,array $extra=[])use($db):string{$saved=[$_GET,$_POST,$_SESSION??[]];$_GET=$query;$_POST=[];$_SESSION=['actor'=>'own-list-admin','csrf'=>str_repeat('a',64)];$accountRows=$finance->accounts();extract($extra,EXTR_SKIP);ob_start();try{require Kulturhus\Verein\Web\Templates::path($template);return ob_get_clean();}catch(Throwable $error){ob_end_clean();throw $error;}finally{[$_GET,$_POST,$_SESSION]=$saved;}};
$source=$cases['front-nojs']['income'];$query=['candidate'=>$source['id'],'account'=>'','bank_page'=>'2','bank_q'=>'Own original','bank_from'=>'2026-10-01','assignment'=>'pending'];$html=$render('entry-payments',$f,$query,['r'=>$f->entry($probe)]);
$check(str_contains($html,'Vorgewählter vorhandener Kontoumsatz')&&str_contains($html,'Own bank &lt;source&gt; 0')&&!str_contains($html,'<em>0</em>'),'linked receipt opens actual own source with escaped original labels');
$dom=new DOMDocument();$dom->loadHTML($html,LIBXML_NOERROR|LIBXML_NOWARNING);$xp=new DOMXPath($dom);$forms=$xp->query('//article[contains(@class,"preferred")]/form/input[@name="transaction_id"]');$check($forms->length===1&&$forms->item(0)->getAttribute('value')===$source['id'],'old intended source is directly reachable beyond the first twenty newer candidates');
$check(str_contains($html,'name="bank_page" value="2"')&&str_contains($html,'name="bank_q" value="Own original"'),'receipt search retains the original bank selection');
$reader=new Finance($db,'own-list-reader');$read=$render('entry-payments',$reader,$query,['r'=>$reader->entry($probe)]);$check(str_contains($read,'Zum ursprünglichen Kontoumsatz')&&!str_contains($read,'method="post"'),'read-only finance role can inspect linked originals without mutation controls');
$foreignView=$render('entry-payments',$f,['candidate'=>$foreignTransaction],['r'=>$f->entry($probe)]);$check(str_contains($foreignView,'Der vorgewählte Kontoumsatz ist nicht verfügbar.')&&!str_contains($foreignView,'Foreign secret source'),'foreign preferred source reveals no original name or account');
$input=$render('manual-finance',$f,['account'=>'','bank_page'=>'2','bank_q'=>'Own original'],['sourceTransaction'=>$f->transactionDetail($source['id']),'kind'=>'income','base'=>['view'=>'finance','tab'=>'receipts'],'inboxDoc'=>null,'inboxDocId'=>'','inboxVersion'=>0,'gemaEventId'=>'','gemaVersion'=>0,'gemaPreset'=>null,'catalogPreset'=>null,'catalogQuote'=>null,'financeEntry'=>null]);
$check(str_contains($input,'name="target_account" value="'.$bank.'"')&&str_contains($input,'Beleg zu vorhandenem Kontoumsatz')&&str_contains($input,'bank_page=2'),'manual receipt uses the actual source account while retaining all-account return context');
$originalHash=static function()use($db):string{$columns=$db->query('SHOW COLUMNS FROM finance_transactions')->fetchAll(PDO::FETCH_COLUMN);$columns=array_values(array_diff($columns,['version']));$sql='SELECT id,SHA2(CAST(JSON_ARRAY('.implode(',',array_map(static fn($c)=>'`'.$c.'`',$columns)).') AS CHAR),256) AS proof FROM finance_transactions ORDER BY club_id,id';$h=hash_init('sha256');foreach($db->query($sql) as $row)hash_update($h,$row['id'].$row['proof']);return hash_final($h);};
if(getenv('DVM_BANK_RECEIPT_BROWSER')==='1'){
 $browserCases=$cases;$selected=getenv('DVM_BANK_RECEIPT_CASE');if($selected!==false&&$selected!==''){if(!isset($cases[$selected]))throw new RuntimeException('Unknown owned browser case');$browserCases=[$selected=>$cases[$selected]];}
 require __DIR__.'/support/free-list-interface-browser-fixture.php';$fixture=ownFreeListInterfaceBrowser($db,['cases'=>$browserCases,'foreign'=>$foreignTransaction]);$root=$fixture['input']['root'];$image=imagecreatetruecolor(40,40);imagefill($image,0,0,imagecolorallocate($image,30,100,70));imagepng($image,$root.'/source-original.png');imagedestroy($image);$original=$originalHash();
 try{$process=proc_open(['node',__DIR__.'/bank-receipt-flow-browser.mjs',$root.'/fixture.json'],[0=>['file','/dev/null','r'],1=>STDOUT,2=>STDERR],$pipes);if(!is_resource($process)||proc_close($process)!==0){foreach(['front','direct'] as $app)echo substr((string)file_get_contents($root.'/'.$app.'.log'),-2500);throw new RuntimeException('Actual linked receipt browser failed');}
 foreach($browserCases as $case)foreach($case as $row){$detail=$f->transactionDetail($row['id']);$history=$f->allocations($row['id'],true);$alloc=array_values(array_filter($history,static fn($l)=>!$l['voided_at']));$check($detail['remaining_cents']===3000&&count($history)===2&&count($alloc)===1&&(int)$alloc[0]['cents']===2000&&$f->entry($alloc[0]['entry_id'])['payment_state']==='paid','actual corrected receipt retains its released original and exactly one active payment');}
 $check((int)$db->query("SELECT COUNT(*) FROM finance_entries WHERE club_id='own-list-club'")->fetchColumn()===1+2*count($browserCases),'rejected source and kind requests create no unintended additional receipt');
 $check($originalHash()===$original,'create approve and allocate preserve every original transaction field except its expected version; no duplicate money is recorded');
 }finally{foreach($fixture['servers'] as [$server,$log]){proc_terminate($server);proc_close($server);fclose($log);}}
}
echo json_encode(['suite'=>'native-bank-receipt-flow','checks'=>$n,'external_actions'=>0],JSON_THROW_ON_ERROR)."\n";
